begin;
select plan(7);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000004"}',true);
select set_config('test.workspace','00000000-0000-4000-8000-000000000005',true);
insert into public.billing_discount_checkouts values('00000000-0000-4000-8000-000000000006',auth.uid(),current_setting('test.workspace')::uuid);
insert into public.purchase_document_versions(id,kind,body,status) values('accept-agreement','agreement','Agreement','published'),('accept-payment','payment_terms','Payment','published');
select throws_ok($$select platform_private.record_checkout_documents('00000000-0000-4000-8000-000000000006','accept-agreement','accept-payment',false)$$,'22023','documents not accepted','explicit confirmation required');
select set_config('test.receipt',platform_private.record_checkout_documents('00000000-0000-4000-8000-000000000006','accept-agreement','accept-payment',true)::text,true);
select is(platform_private.record_checkout_documents('00000000-0000-4000-8000-000000000006','accept-agreement','accept-payment',true)::text,current_setting('test.receipt'),'retry returns original record');
select throws_ok($$select platform_private.record_checkout_documents('00000000-0000-4000-8000-000000000006','other','accept-payment',true)$$,'22023','checkout acceptance conflict','retry cannot change accepted revision');
select set_config('test.workspace','00000000-0000-4000-8000-000000000007',true);
select throws_ok($$select platform_private.record_checkout_documents('00000000-0000-4000-8000-000000000006','accept-agreement','accept-payment',true)$$,'42501','checkout access denied','workspace permission checked on retry');
set local role authenticated;
select throws_ok($$select * from public.checkout_document_acceptances$$,'42501',null,'direct read denied');
select throws_ok($$select platform_private.record_checkout_documents(null,null,null,true)$$,'42501',null,'direct recording denied');
reset role;
select is((select count(*)::int from public.checkout_document_acceptances),1,'only one acceptance');
select * from finish();
rollback;
